private void rejectIfInSuspensionWindow(String raceId, Long elapsedMillis) {
    if (elapsedMillis == null) return;
    List<NetTimingCalculator.SuspensionEvent> events = resumedEventViews(raceId);
    if (events.isEmpty()) return;
    String violation = NetTimingCalculator.windowViolation(elapsedMillis, events);
    if (violation != null) throw new UnprocessableEntityException(violation);
}

